  1→package transcript
  2→
  3→import (
  4→	"bufio"
  5→	"bytes"
  6→	"encoding/json"
  7→	"io"
  8→	"strings"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 11→)
 12→
 13→// droppedTypes are entry types that carry no parser-relevant data.
 14→var droppedTypes = map[string]bool{
 15→	"progress":              true,
 16→	"file-history-snapshot": true,
 17→	"queue-operation":       true,
 18→	"system":                true,
 19→}
 20→
 21→// CompactOptions provides metadata fields written to every output line.
 22→type CompactOptions struct {
 23→	Agent      string // e.g. "claude-code"
 24→	CLIVersion string // e.g. "0.42.0"
 25→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 26→}
 27→
 28→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 29→//
 30→// The output format puts version, agent, and cli_version on every line,
 31→// flattens the message wrapper, and splits user tool results into separate entries:
 32→//
 33→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 34→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 35→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 36→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 37→	truncated := SliceFromLine(content, opts.StartLine)
 38→	if truncated == nil {
 39→		truncated = []byte{}
 40→	}
 41→
 42→	reader := bufio.NewReader(bytes.NewReader(truncated))
 43→	var result []byte
 44→
 45→	for {
 46→		lineBytes, err := reader.ReadBytes('\n')
 47→		if err != nil && err != io.EOF {
 48→			return nil, err
 49→		}
 50→
 51→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 52→			outputLines := convertLine(lineBytes, opts)
 53→			for _, ol := range outputLines {
 54→				result = append(result, ol...)
 55→				result = append(result, '\n')
 56→			}
 57→		}
 58→
 59→		if err == io.EOF {
 60→			break
 61→		}
 62→	}
 63→
 64→	return result, nil
 65→}
 66→
 67→// userAliases maps transcript type/role values to the canonical "user" kind.
 68→var userAliases = map[string]bool{
 69→	"user":  true,
 70→	"human": true,
 71→}
 72→
 73→// assistantAliases maps transcript type/role values to the canonical "assistant" kind.
 74→var assistantAliases = map[string]bool{
 75→	"assistant": true,
 76→	"gemini":    true,
 77→}
 78→
 79→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 80→// transcript line. It checks the "type" field, then falls back to "role".
 81→// Returns "" for unrecognised or dropped entries.
 82→func normalizeKind(raw map[string]json.RawMessage) string {
 83→	// Try "type" first, then "role".
 84→	kind := unquote(raw["type"])
 85→	if kind == "" {
 86→		kind = unquote(raw["role"])
 87→	}
 88→
 89→	if droppedTypes[kind] {
 90→		return ""
 91→	}
 92→	if userAliases[kind] {
 93→		return "user"
 94→	}
 95→	if assistantAliases[kind] {
 96→		return "assistant"
 97→	}
 98→	return ""
 99→}
100→
101→// unwrapEnvelope handles envelope formats where the actual message is nested.
102→// Factory AI Droid uses {"type":"message","message":{"role":"user","content":...}}.
103→// If the line is an envelope, it returns the inner message merged with outer fields
104→// (timestamp, id). Otherwise it returns raw unchanged.
105→func unwrapEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
106→	kind := unquote(raw["type"])
107→	if kind != "message" {
108→		return raw
109→	}
110→
111→	msgRaw, ok := raw["message"]
112→	if !ok {
113→		return raw
114→	}
115→
116→	var inner map[string]json.RawMessage
117→	if json.Unmarshal(msgRaw, &inner) != nil {
118→		return raw
119→	}
120→
121→	// The inner message should have a "role" field — check it resolves to a known kind.
122→	innerRole := unquote(inner["role"])
123→	if !userAliases[innerRole] && !assistantAliases[innerRole] {
124→		return raw
125→	}
126→
127→	// Build a merged view: inner fields take precedence, but carry over outer
128→	// fields (timestamp, id) that the inner message may lack.
129→	merged := make(map[string]json.RawMessage, len(inner)+2)
130→	// Copy outer timestamp if present.
131→	if v, has := raw["timestamp"]; has {
132→		merged["timestamp"] = v
133→	}
134→	// Copy outer id as fallback.
135→	if v, has := raw["id"]; has {
136→		merged["id"] = v
137→	}
138→	// Copy all inner fields (overrides outer if keys collide).
139→	for k, v := range inner {
140→		merged[k] = v
141→	}
142→	// Promote "role" to "type" so normalizeKind resolves it.
143→	if _, hasType := merged["type"]; !hasType {
144→		merged["type"] = inner["role"]
145→	}
146→
147→	// Re-wrap content into a "message" field so converters find it.
148→	// The inner message IS the message wrapper for converters.
149→	merged["message"] = msgRaw
150→
151→	return merged
152→}
153→
154→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
155→// A user entry with tool_result blocks produces multiple output lines.
156→func convertLine(lineBytes []byte, opts CompactOptions) [][]byte {
157→	var raw map[string]json.RawMessage
158→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
159→		return nil
160→	}
161→
162→	// Unwrap envelope formats (e.g. Factory AI Droid's type:"message" wrapper).
163→	raw = unwrapEnvelope(raw)
164→
165→	switch normalizeKind(raw) {
166→	case "assistant":
167→		return convertAssistant(raw, opts)
168→	case "user":
169→		return convertUser(raw, opts)
170→	default:
171→		return nil // drop unknown types in the new format
172→	}
173→}
174→
175→func convertAssistant(raw map[string]json.RawMessage, opts CompactOptions) [][]byte {
176→	// Hoist id and content from message to top level
177→	var id, content json.RawMessage
178→	if msgRaw, ok := raw["message"]; ok {
179→		var msg map[string]json.RawMessage
180→		if json.Unmarshal(msgRaw, &msg) == nil {
181→			id = msg["id"]
182→			if contentRaw, ok := msg["content"]; ok {
183→				content = stripAssistantContent(contentRaw)
184→			}
185→		}
186→	}
187→
188→	b := marshalOrdered(
189→		"v", mustMarshal(1),
190→		"agent", mustMarshal(opts.Agent),
191→		"cli_version", mustMarshal(opts.CLIVersion),
192→		"type", mustMarshal("assistant"),
193→		"ts", raw["timestamp"],
194→		"id", id,
195→		"content", content,
196→	)
197→	if b == nil {
198→		return nil
199→	}
200→	return [][]byte{b}
201→}
202→
203→func convertUser(raw map[string]json.RawMessage, opts CompactOptions) [][]byte {
204→	var lines [][]byte
205→	ts := raw["timestamp"]
206→
207→	// Parse message content to separate text from tool_results
208→	var textContent string
209→	var toolResults []toolResultEntry
210→
211→	if msgRaw, ok := raw["message"]; ok {
212→		var msg map[string]json.RawMessage
213→		if json.Unmarshal(msgRaw, &msg) == nil {
214→			if contentRaw, ok := msg["content"]; ok {
215→				textContent, toolResults = extractUserContent(contentRaw)
216→			}
217→		}
218→	}
219→
220→	// Emit the user text entry
221→	b := marshalOrdered(
222→		"v", mustMarshal(1),
223→		"agent", mustMarshal(opts.Agent),
224→		"cli_version", mustMarshal(opts.CLIVersion),
225→		"type", mustMarshal("user"),
226→		"ts", ts,
227→		"content", mustMarshal(textContent),
228→	)
229→	if b != nil {
230→		lines = append(lines, b)
231→	}
232→
233→	// Emit separate user_tool_result entries.
234→	//
235→	// Note: full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
236→	// When there are multiple tool_result blocks, each user_tool_result line gets the same
237→	// minimized result. This is a known limitation of the source format — per-tool-use-id
238→	// result data is not available.
239→	var minimizedResult json.RawMessage
240→	if turRaw, ok := raw["toolUseResult"]; ok {
241→		minimizedResult = minimizeToolUseResult(turRaw)
242→	}
243→
244→	for _, tr := range toolResults {
245→		result := minimizedResult
246→		if result == nil {
247→			result = mustMarshal(map[string]interface{}{})
248→		}
249→
250→		b := marshalOrdered(
251→			"v", mustMarshal(1),
252→			"agent", mustMarshal(opts.Agent),
253→			"cli_version", mustMarshal(opts.CLIVersion),
254→			"type", mustMarshal("user_tool_result"),
255→			"ts", ts,
256→			"tool_use_id", mustMarshal(tr.toolUseID),
257→			"result", result,
258→		)
259→		if b != nil {
260→			lines = append(lines, b)
261→		}
262→	}
263→
264→	return lines
265→}
266→
267→type toolResultEntry struct {
268→	toolUseID string
269→}
270→
271→// extractUserContent separates user message content into text and tool_result entries.
272→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
273→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
274→	// String content
275→	var str string
276→	if json.Unmarshal(contentRaw, &str) == nil {
277→		return textutil.StripIDEContextTags(str), nil
278→	}
279→
280→	// Array content
281→	var blocks []map[string]json.RawMessage
282→	if json.Unmarshal(contentRaw, &blocks) != nil {
283→		return "", nil
284→	}
285→
286→	var texts []string
287→	var toolResults []toolResultEntry
288→
289→	for _, block := range blocks {
290→		blockType := unquote(block["type"])
291→
292→		if blockType == "tool_result" {
293→			toolResults = append(toolResults, toolResultEntry{
294→				toolUseID: unquote(block["tool_use_id"]),
295→			})
296→			continue
297→		}
298→
299→		if blockType == "text" {
300→			stripped := textutil.StripIDEContextTags(unquote(block["text"]))
301→			if stripped != "" {
302→				texts = append(texts, stripped)
303→			}
304→		}
305→	}
306→
307→	text := ""
308→	if len(texts) > 0 {
309→		text = texts[0]
310→		var sb strings.Builder
311→		for i := 1; i < len(texts); i++ {
312→			sb.WriteString("\n\n" + texts[i])
313→		}
314→		text += sb.String()
315→	}
316→
317→	return text, toolResults
318→}
319→
320→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
321→	// String content — keep as-is
322→	var str string
323→	if json.Unmarshal(contentRaw, &str) == nil {
324→		return contentRaw
325→	}
326→
327→	// Array of content blocks
328→	var blocks []map[string]json.RawMessage
329→	if json.Unmarshal(contentRaw, &blocks) != nil {
330→		return contentRaw
331→	}
332→
333→	var result []map[string]json.RawMessage
334→	for _, block := range blocks {
335→		blockType := unquote(block["type"])
336→
337→		// Drop thinking blocks
338→		if blockType == "thinking" || blockType == "redacted_thinking" {
339→			continue
340→		}
341→
342→		// Strip tool_use: keep type, id, name, input — drop caller
343→		if blockType == "tool_use" {
344→			stripped := make(map[string]json.RawMessage)
345→			copyField(stripped, block, "type")
346→			copyField(stripped, block, "id")
347→			copyField(stripped, block, "name")
348→			copyField(stripped, block, "input")
349→			result = append(result, stripped)
350→			continue
351→		}
352→
353→		// Other block types (text, image) — keep as-is
354→		result = append(result, block)
355→	}
356→
357→	b, err := json.Marshal(result)
358→	if err != nil {
359→		return contentRaw
360→	}
361→	return b
362→}
363→
364→// minimizeToolUseResult strips a toolUseResult to only the fields the API needs.
365→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
366→	var obj map[string]json.RawMessage
367→	if json.Unmarshal(raw, &obj) != nil {
368→		return raw
369→	}
370→
371→	return marshalOrdered(
372→		"type", obj["type"],
373→		"file", obj["file"],
374→		"error", obj["error"],
375→		"answers", obj["answers"],
376→	)
377→}
378→
379→// marshalOrdered produces a JSON object with keys in the given order.
380→// Pairs with nil values are omitted.
381→func marshalOrdered(pairs ...interface{}) []byte {
382→	var buf bytes.Buffer
383→	buf.WriteByte('{')
384→	first := true
385→	for i := 0; i < len(pairs)-1; i += 2 {
386→		key := pairs[i].(string)
387→		val, _ := pairs[i+1].(json.RawMessage)
388→		if val == nil {
389→			continue
390→		}
391→		if !first {
392→			buf.WriteByte(',')
393→		}
394→		keyJSON, _ := json.Marshal(key)
395→		buf.Write(keyJSON)
396→		buf.WriteByte(':')
397→		buf.Write(val)
398→		first = false
399→	}
400→	buf.WriteByte('}')
401→	return buf.Bytes()
402→}
403→
404→func mustMarshal(v interface{}) json.RawMessage {
405→	b, _ := json.Marshal(v)
406→	return b
407→}
408→
409→func copyField(dst, src map[string]json.RawMessage, key string) {
410→	if v, ok := src[key]; ok {
411→		dst[key] = v
412→	}
413→}
414→
415→func unquote(raw json.RawMessage) string {
416→	var s string
417→	if json.Unmarshal(raw, &s) == nil {
418→		return s
419→	}
420→	return ""
421→}
